import * as React from "react";
import { Input as InputPrimitive } from "@base-ui/react/input";

import { cn } from "./kgcraft-utils";

function Input({ className, type, ...props }: React.ComponentProps<"input">) {
  return (
    <InputPrimitive
      type={type}
      data-slot="input"
      className={cn(
        "cn-input border-kgcraft-input selection:bg-kgcraft-primary selection:text-kgcraft-primary-foreground file:text-kgcraft-foreground placeholder:text-kgcraft-muted-foreground dark:bg-kgcraft-input/30 h-9 w-full min-w-0 rounded-md border bg-transparent px-3 py-1 text-base shadow-xs transition-[color,box-shadow] outline-none file:inline-flex file:h-7 file:border-0 file:bg-transparent file:text-sm file:font-medium disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50 md:text-sm",
        "focus-visible:border-kgcraft-ring focus-visible:ring-kgcraft-ring/50 focus-visible:ring-[3px]",
        "aria-invalid:border-kgcraft-destructive aria-invalid:ring-kgcraft-destructive/20 dark:aria-invalid:ring-kgcraft-destructive/40",
        className,
      )}
      {...props}
    />
  );
}

export { Input };

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
